#!/usr/bin/env python3
"""Regenerate the static outline page from the reviewed, committed data."""
import json
from pathlib import Path
from html import escape as e
root = Path(__file__).resolve().parents[2]
data = json.loads((root / 'assets/notes/outlines.json').read_text(encoding='utf8'))
bs, chem = data['business_studies'], data['chemistry']
def card(c):
 im=('<figure><img loading="lazy" src="/'+e(c['image'])+'" alt="'+e(c['figure'])+'"><figcaption>NCERT figure '+e(c['fig'])+' · '+e(c['figure'])+' · PDF page '+str(c['page'])+' · source crop, not AI-drawn</figcaption></figure>') if 'image' in c else ''
 li=lambda a: ''.join('<li>'+e(x)+'</li>' for x in a)
 return '<article id="'+e(c['id'])+'"><div class="eyebrow">'+e(c['source'])+'</div><h3>'+e(c['title'])+'</h3><p>'+e(c['summary'])+'</p><div class="cols"><section><h4>Sections</h4><ul>'+li(c['sections'])+'</ul></section><section><h4>Objectives</h4><ul>'+li(c['objectives'])+'</ul></section></div><h4>Key terms</h4><p class="terms">'+e(' · '.join(c['terms']))+'</p>'+im+'</article>'

business_check = '''<div class="notebox"><h2 class="nb-title">Sources and gaps — Business Studies</h2>
<p><strong>Sources.</strong> Eleven chapter outlines (lebs101.pdf–lebs108.pdf, lebs201.pdf–lebs203.pdf) are derived from the supplied NCERT Class 12 Business Studies English chapter PDFs; each outline records its source filename and SHA-256 hash, and the source PDFs are not published on the site. Unit 10, Financial Markets, was not in the supplied chapters; it is drawn from the published CBSE 2026–27 Business Studies syllabus (subject 054), <a href="https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/BusinessStudies_SecP2_2026-27.pdf">CBSE syllabus ↗</a>. Unit numbering follows that syllabus (Part A units 1–8, Part B units 9–12).</p>
<p><strong>Gaps.</strong> Part C Project Work (20 marks) is not covered. There is no question bank and no full chapter prose; the outlines are study aids. Unit 10 wording comes from the syllabus, not from NCERT text. The Consumer Protection outline applies the Consumer Protection Act, 2019 named by the syllabus; a conflicting 1986-Act excerpt in the staged source is not used. Chapter sub-headings were mapped to the 2026–27 syllabus, and a small number of syllabus headings were added even where the staged principal-heading selection did not carry them. The outlines were checked against the published CBSE 2026–27 syllabus by Upay; they are <strong>not certified by CBSE</strong> and do not exhaust every examinable topic.</p></div>'''

chem_check = '''<div class="notebox"><h2 class="nb-title">Sources and gaps — Chemistry</h2>
<p><strong>Sources.</strong> Ten unit outlines are derived from the supplied NCERT Class 12 Chemistry English reprint PDFs (lech101.pdf–lech105.pdf and lech201.pdf–lech205.pdf); each outline records its source filename and SHA-256 hash, and the source PDFs are not published on the site. Unit mapping and the 2026–27 theory marks (70 total) follow the published CBSE 2026–27 Chemistry syllabus (subject 043), <a href="https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/Chemistry_SecP2_2026-27.pdf">CBSE syllabus ↗</a>. The two supplied answer appendices (lech1an.pdf, lech2an.pdf) were identified and deliberately excluded. Figure provenance, hashes and any AI-origin status are recorded in <code>assets/img/notes/manifest.json</code>.</p>
<p><strong>Gaps.</strong> The practical syllabus and project work (30 marks) are not covered. The four formative-only (not-summative) topics — Surface Chemistry; General Principles and Processes of Isolation of Elements; Polymers; Chemistry in Everyday Life — are not included as such, consistent with their 2026–27 formative-only status. There is no question bank and no full chapter prose. The figure inventory is incomplete: one reviewed source-PDF crop is shown per chapter (no AI-drawn figures so far); the remaining figures can only be extracted when the source PDFs are re-supplied, after which the manifest will be completed. The outlines were checked against the published CBSE 2026–27 syllabus by Upay; they are <strong>not certified by CBSE</strong> and do not exhaust every examinable topic. Any AI-generated questions, if added later, will be labelled <strong>practice, not board-verified</strong>; none are included here.</p></div>'''

styles = '<style>body{margin:0;background:#f6f5ef;color:#162b27;font:16px/1.6 system-ui,sans-serif}main{max-width:1000px;margin:auto;padding:32px 22px 80px}a{color:#087357}header{padding:28px 0}h1{font-size:clamp(2rem,5vw,3.4rem);line-height:1.1;margin:12px 0}h2{margin:40px 0 10px;font-size:1.8rem}h3{font-size:1.4rem;margin:0 0 8px}h4{margin:12px 0 5px}article{scroll-margin-top:20px;background:white;border:1px solid #dbe5df;border-radius:16px;padding:24px;margin:16px 0;box-shadow:0 4px 18px #1428200c}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:#087357;font-weight:700}.notice{border-left:4px solid #d8a83b;background:#fff8e5;padding:16px 20px;border-radius:6px}.notebox{border:1px solid #dbe5df;background:#eef4ef;border-radius:12px;padding:16px 20px;margin:14px 0}.nb-title{font-size:1.05rem;margin:0 0 8px}.notebox p{margin:6px 0;font-size:14.5px}.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:8px 32px}ul{padding-left:22px;margin:4px 0}.terms{color:#345c51}figure{margin:20px 0 0;border-top:1px solid #e1eae5;padding-top:16px}img{display:block;max-width:100%;max-height:320px;object-fit:contain;object-position:left}figcaption{font-size:13px;color:#52665e}nav a{display:inline-block;margin:4px 16px 4px 0}code{background:#e4ece7;border-radius:4px;padding:1px 5px;font-size:13px}</style>'

html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Class 12 outlines | Upay</title>'+styles+'</head><body><main><a href="/">← Back to Upay</a><header><div class="eyebrow">CBSE · Class 12 · English · 2026–27</div><h1>Study outlines</h1><p>Short, syllabus-mapped study outlines, not full textbook chapters. Select a subject to begin.</p><nav><a href="#business">Business Studies</a><a href="#chemistry">Chemistry</a></nav></header><div class="notice"><strong>About verification.</strong> Topics were checked against the published CBSE 2026–27 syllabus, not certified by CBSE. These are concise study aids, not a complete syllabus, official notes or an answer key. Check your board and year. Any AI-generated questions are <strong>practice, not board-verified</strong>; none are included here.</div><h2 id="business">Business Studies</h2><p>Eleven supplied chapter outlines and a Financial Markets outline drawn from the CBSE syllabus, mapped to subject 054. Project work is not covered. <a href="https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/BusinessStudies_SecP2_2026-27.pdf">CBSE syllabus ↗</a></p><p class="notice"><strong>Consumer protection:</strong> CBSE prescribes the Consumer Protection Act, 2019. The staged source’s summary refers to the older 1986 Act; that conflicting excerpt is not reproduced here. The 2019 Act repeals the 1986 Act subject to savings (section 107). <a href="https://www.indiacode.nic.in/handle/123456789/15256">India Code ↗</a></p>'+business_check+''.join(card(c) for c in bs)+'<h2 id="chemistry">Chemistry</h2><p>Ten chapter outlines from the supplied NCERT reprint, mapped to CBSE subject 043. Practicals and project work are not covered. The figure inventory is incomplete; see the manifest note below and the Sources and gaps panel. The two supplied answer appendices are not included. <a href="https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/Chemistry_SecP2_2026-27.pdf">CBSE syllabus ↗</a></p>'+chem_check+''.join(card(c) for c in chem)+'</main></body></html>'
(root/'assets/notes/index.html').write_text(html)
print('wrote assets/notes/index.html')
